export declare const cssText = "\n.dsh_me_section {\n  display: flex;\n  flex-direction: column;\n  gap: 14px;\n  min-width: 0;\n}\n.dsh_me_head {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  min-width: 0;\n}\n.dsh_me_title {\n  margin: 0;\n  color: var(--dsw-alias-label-primary);\n  font-size: 18px;\n  line-height: 26px;\n  font-weight: 600;\n}\n.dsh_me_subtitle {\n  margin: 0;\n  color: var(--dsw-alias-label-tertiary);\n  font-size: 13px;\n  line-height: 20px;\n}\n.dsh_me_pref {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 11px 14px;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 12px;\n  background: var(--dsw-alias-bg-layer-1);\n}\n.dsh_me_pref_text {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  min-width: 0;\n}\n.dsh_me_pref_title {\n  font-size: 13px;\n  font-weight: 600;\n  color: var(--dsw-alias-label-primary);\n}\n.dsh_me_pref_desc {\n  font-size: 12px;\n  line-height: 18px;\n  color: var(--dsw-alias-label-tertiary);\n}\n.dsh_me_actions {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n.dsh_me_btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n  height: 32px;\n  padding: 0 16px;\n  border-radius: 8px;\n  border: 1px solid var(--dsw-alias-border-l2);\n  background: var(--dsw-alias-bg-layer-1);\n  color: var(--dsw-alias-label-primary);\n  font: inherit;\n  font-size: 13px;\n  font-weight: 600;\n  cursor: pointer;\n}\n.dsh_me_btn:hover:not(:disabled) {\n  background: var(--dsw-alias-interactive-bg-hover);\n}\n.dsh_me_btn:disabled {\n  opacity: .55;\n  cursor: not-allowed;\n}\n.dsh_me_btn_save {\n  background: var(--dsw-alias-brand-primary);\n  border-color: transparent;\n  color: var(--dsw-alias-label-primary-foreground);\n}\n.dsh_me_btn_save:hover:not(:disabled) {\n  background: var(--dsw-alias-brand-primary-hover, var(--dsw-alias-brand-primary));\n}\n.dsh_me_toast {\n  color: var(--dsw-alias-label-tertiary);\n  font-size: 13px;\n  line-height: 20px;\n}\n.dsh_me_toast_error {\n  color: var(--dsw-alias-danger, #ef4444);\n}\n.dsh_me_empty,\n.dsh_me_error {\n  color: var(--dsw-alias-label-tertiary);\n  font-size: 14px;\n  line-height: 22px;\n  padding: 8px 0;\n}\n.dsh_me_error {\n  color: var(--dsw-alias-danger, #ef4444);\n}\n.dsh_me_card {\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 12px;\n  background: var(--dsw-alias-bg-layer-1);\n  overflow: hidden;\n}\n.dsh_me_card_header {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 11px 14px;\n  border: 0;\n  width: 100%;\n  background: var(--dsw-alias-bg-layer-2, var(--dsw-alias-bg-layer-1));\n  color: var(--dsw-alias-label-primary);\n  font: inherit;\n  font-size: 13px;\n  font-weight: 600;\n  cursor: pointer;\n  text-align: left;\n}\n.dsh_me_card_header:hover {\n  background: var(--dsw-alias-interactive-bg-hover);\n}\n.dsh_me_chevron {\n  flex: none;\n  width: 14px;\n  height: 14px;\n  color: var(--dsw-alias-label-dimmed);\n  transition: transform .18s ease;\n}\n.dsh_me_card_collapsed .dsh_me_chevron {\n  transform: rotate(-90deg);\n}\n.dsh_me_card_title {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.dsh_me_count {\n  flex: none;\n  font-size: 11px;\n  font-weight: 600;\n  color: var(--dsw-alias-label-secondary);\n  background: var(--dsw-alias-interactive-bg-hover);\n  padding: 2px 9px;\n  border-radius: 999px;\n}\n.dsh_me_row {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n  padding: 11px 14px;\n  border-top: 1px solid var(--dsw-alias-border-l2);\n}\n.dsh_me_model {\n  flex: 1;\n  min-width: 0;\n  font-family: ui-monospace, \"SF Mono\", \"Fira Code\", monospace;\n  font-size: 12.5px;\n  color: var(--dsw-alias-label-primary);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.dsh_me_row_dim .dsh_me_model {\n  color: var(--dsw-alias-label-dimmed);\n}\n.dsh_me_toggle {\n  flex: none;\n  position: relative;\n  width: 38px;\n  height: 22px;\n  border: 0;\n  padding: 0;\n  border-radius: 999px;\n  background: var(--dsw-alias-bg-layer-3, var(--dsw-alias-border-l2));\n  cursor: pointer;\n  transition: background .2s;\n}\n.dsh_me_toggle::after {\n  content: \"\";\n  position: absolute;\n  top: 2px;\n  left: 2px;\n  width: 18px;\n  height: 18px;\n  background: var(--dsw-alias-label-primary-foreground);\n  border-radius: 50%;\n  transition: transform .2s cubic-bezier(.4,0,.2,1);\n  box-shadow: 0 1px 2px rgba(0,0,0,.3);\n}\n.dsh_me_toggle_on {\n  background: var(--dsw-alias-brand-primary);\n}\n.dsh_me_toggle_on::after {\n  transform: translateX(16px);\n}\n.dsh_me_chips {\n  display: flex;\n  align-items: stretch;\n  flex: none;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 8px;\n  overflow: hidden;\n}\n.dsh_me_row_dim .dsh_me_chips {\n  opacity: .4;\n  pointer-events: none;\n}\n.dsh_me_chip {\n  --eff: #888;\n  min-width: 42px;\n  height: 24px;\n  border: 0;\n  padding: 0 7px;\n  font: inherit;\n  font-size: 10px;\n  font-weight: 600;\n  cursor: pointer;\n  color: var(--dsw-alias-label-secondary);\n  background: var(--dsw-alias-bg-layer-1);\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 4px;\n}\n.dsh_me_chip + .dsh_me_chip {\n  border-left: 1px solid var(--dsw-alias-border-l2);\n}\n.dsh_me_chip_dot {\n  width: 5px;\n  height: 5px;\n  border-radius: 50%;\n  background: var(--eff);\n}\n.dsh_me_chip:hover:not(.dsh_me_chip_on) {\n  background: var(--dsw-alias-interactive-bg-hover);\n  color: var(--dsw-alias-label-primary);\n}\n.dsh_me_chip_on {\n  background: var(--dsw-alias-brand-primary);\n  color: var(--dsw-alias-label-primary-foreground);\n}\n.dsh_me_chip_on .dsh_me_chip_dot {\n  background: var(--dsw-alias-label-primary-foreground);\n}\n@media (max-width: 720px) {\n  .dsh_me_row { flex-wrap: wrap; }\n  .dsh_me_chips { order: 10; width: 100%; }\n}\n";
